# shellcheck shell=bash
# Git identity. povy generates a Git config from config.toml and includes it from a
# marked block at the top of the user's global config. Whatever comes after the
# block keeps precedence, so povy reports a [user] there instead of removing it.
#
# Generated files, in POVY_GIT_DIR:
#   config       the default identity, and one includeIf per directory identity
#   identity-N   the identity used in the repositories under that directory

POVY_GIT_HEADER='# Generated by povy apply from config.toml. Changes here are overwritten.'

# Git reads ~/.gitconfig, or only the XDG file when ~/.gitconfig does not exist.
git_global_file() {
  local xdg="${XDG_CONFIG_HOME:-$HOME/.config}/git/config"
  if [ ! -e "$HOME/.gitconfig" ] && [ ! -L "$HOME/.gitconfig" ] && [ -e "$xdg" ]; then
    printf '%s\n' "$xdg"
  else
    printf '%s\n' "$HOME/.gitconfig"
  fi
}

# Writes a path as a Git config value, with ~/ when possible so that the block
# stays valid in a dotfiles repository shared between machines.
git_path_literal() {
  local path=$1 rest
  case "$path" in
    "$HOME"/*)
      rest=${path#"$HOME"/}
      if [[ "$rest" =~ ^[A-Za-z0-9._/-]+$ ]]; then
        # shellcheck disable=SC2088 # Git expands ~/ itself.
        printf '~/%s' "$rest"
        return 0
      fi
      ;;
  esac
  path=${path//\\/\\\\}
  path=${path//\"/\\\"}
  printf '"%s"' "$path"
}

git_block() {
  printf '%s\n' "$POVY_BLOCK_START"
  echo '# Managed by povy. Edits inside this block are overwritten.'
  echo '[include]'
  printf '\tpath = %s\n' "$(git_path_literal "$POVY_GIT_DIR/config")"
  printf '%s\n' "$POVY_BLOCK_END"
}

# git config -f does the quoting, so names and paths need no escaping here.
git_write_identity() {
  local file=$1 name=$2 email=$3
  printf '%s\n' "$POVY_GIT_HEADER" >"$file"
  git config -f "$file" user.name "$name" &&
    git config -f "$file" user.email "$email"
}

# Git compares gitdir: with the repository's real path. It resolves ~/ itself, but
# not an absolute pattern, so an existing directory is written as its real path:
# /var/... never matches on macOS, where /var is a link to /private/var.
git_identity_pattern() {
  local dir=$1
  case "$dir" in
    /*) [ ! -d "$dir" ] || dir="$(cd -P "$dir" && pwd)/" ;;
  esac
  printf '%s' "${dir%//}"
}

# Prints "dir<TAB>name<TAB>email" for each identity by directory, those of
# [[identities]] and those of the contexts, parents first: Git applies every
# includeIf that matches, in order, so the deepest directory wins.
git_identities() {
  {
    printf '%s\n' "$CFG_IDENTITIES"
    printf '%s\n' "$CFG_CONTEXTS" | awk -F'\t' 'NF && $4 != "" { print $2 "\t" $3 "\t" $4 }'
  } | awk -F'\t' 'NF { print length($1) "\t" NR "\t" $0 }' | sort -t$'\t' -k1,1n -k2,2n | cut -f3-
}

# Renders every generated file into dir. Include paths are relative, and Git
# resolves them from the including file.
git_render() {
  local dir=$1 index=0 idir iname iemail
  git_write_identity "$dir/config" "$CFG_NAME" "$CFG_EMAIL" || return 1
  while IFS=$'\t' read -r idir iname iemail; do
    [ -n "$idir" ] || continue
    idir=$(git_identity_pattern "$idir")
    index=$((index + 1))
    git_write_identity "$dir/identity-$index" "$iname" "$iemail" || return 1
    git config -f "$dir/config" "includeIf.gitdir:$idir.path" "identity-$index" || return 1
  done <<<"$(git_identities)"
}

# Prints, once each, the files that set user.name or user.email after the povy
# include of the global config, and so override the identities povy sets.
git_overriding_files() {
  local global origin value
  global=$(git_global_file)
  [ -f "$global" ] || return 0
  git config -f "$global" --includes --show-origin -z --get-regexp '^user\.(name|email)$' 2>/dev/null |
    while IFS= read -r -d '' origin && IFS= read -r -d '' value; do
      origin=${origin#file:}
      case "$origin" in
        "$POVY_GIT_DIR"/*) ;;
        *) printf '%s\n' "$origin" ;;
      esac
    done | awk '!seen[$0]++'
}

git_apply() {
  local stage file name overriding
  if ! command -v git >/dev/null 2>&1; then
    warn "git is not installed; the Git identity is not set"
    return 0
  fi
  stage=$(mktemp -d "$POVY_STATE_DIR/git.XXXXXX") || die "cannot write in $POVY_STATE_DIR"
  if ! git_render "$stage"; then
    rm -rf "$stage"
    die "could not generate the Git configuration"
  fi
  for file in "$stage"/*; do
    install_file "$file" "$POVY_GIT_DIR/${file##*/}" 644
  done
  for file in "$POVY_GIT_DIR"/identity-*; do
    name=${file##*/}
    [ -e "$file" ] && [ ! -e "$stage/$name" ] || continue
    rm -f "$file" || die "cannot remove $file"
    POVY_WRITTEN=$((POVY_WRITTEN + 1))
    info "removed $file"
  done
  rm -rf "$stage"

  block_apply "$(git_global_file)" "$(git_block)"

  overriding=$(git_overriding_files)
  if [ -n "$overriding" ]; then
    warn "these files set user.name or user.email after the povy include, so they override it:"
    info "$overriding"
    info "Remove those settings, or move them to config.toml."
  fi
}
